import json, math
data=json.load(open("Hanahuac/Resources/river-paths.json"))
def d(a,b): return math.hypot(a[0]-b[0],a[1]-b[1])
worst=[]
for e in data:
    for pi,part in enumerate(e["parts"]):
        for a,b in zip(part,part[1:]):
            worst.append((d(a,b),e["id"],pi))
worst.sort(reverse=True)
print("Top 12 intra-part vertex jumps (deg):")
for g,rid,pi in worst[:12]:
    print(f"  {g:.3f}  {rid} part{pi}")
# parts per river distribution
pp={e["id"]:len(e["parts"]) for e in data}
print("max parts/river:", max(pp.values()), "->", [k for k,v in pp.items() if v==max(pp.values())])
print("lena parts:", pp["lena"])
